function [csa,csaRYG]=CSA(spd)
%Fotios's cone surface area
%selectcards = numbers of MunsellCRI card to use (default = first 8)
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

selectcards=(1:8);
uvp=xyz2uvY(spd2xyz(spd,2,0));%source chromaticity in 1976 uv prime chrom. diagram
[ga,gaRYG]=GA(spd,selectcards);%calculate gamut area in 1976 uv prime chrom. diagram
r=sqrt(ga./pi);
rRYG=sqrt(gaRYG./pi);%calculate radius of base of cone
wp=1-(uvp(1)+uvp(2));%perpendicular height of cone
L=sqrt(wp.^2+r.^2);
LRYG=sqrt(wp.^2+rRYG.^2);%length of slope of cone

csa=pi.*r.^2+pi.*r.*L;
csaRYG=pi.*rRYG.^2+pi.*rRYG.*LRYG;%cone surface area
end
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

function [ga,gaRYG]=GA(spd,selectcards)
%calculate gamut area  1976 space 
